import { test, expect } from '@playwright/test';
import { createHash } from 'node:crypto';
import { readFile } from 'node:fs/promises';

// These are actual lexical distinctions, rather than snapshots regenerated by
// the implementation under test. The source has only one merged bare AM/mar.
// POS assertions (including upstream a.m./AM and canonical Apr. labels) only
// preserve the current display projection; they do not approve those grammar
// labels or perform a whole-dictionary POS audit. This scope checks routing.
const cases = [
  ['Apr.', 'Apr.', '四月', 'proper noun'],
  ['apr.', 'Apr.', '四月', 'proper noun'],
  ['"Apr."', 'Apr.', '四月', 'proper noun'],
  ['“Apr.”?!', 'Apr.', '四月', 'proper noun'],
  ['Ａｐｒ．', 'Apr.', '四月', 'proper noun'],
  ['APR', 'APR', '年百分率', 'abbreviation'],
  ['a.m.', 'a.m.', '上午', 'adjective'],
  ['AM', 'AM', 'be的单数第一人称', 'noun'],
  ['Mar.', 'Mar.', '三月', 'noun'],
  ['mar', 'mar', '损毁', 'verb'],
  ['data.', 'data', '数据', 'noun'],
  ['past.', 'past', '过去', 'noun'],
  ['happy.', 'happy', '快乐', 'adjective'],
  ['What have we got to lose?', 'What have we got to lose?', '损失', 'idiomatic phrase']
];
const manifest = JSON.parse(await readFile(new URL('../../../vocab/data/expanded-dictionary/manifest.json', import.meta.url), 'utf8'));
const bucket = value => {
  let hash = 2166136261;
  for (const char of value.toLowerCase()) { hash ^= char.codePointAt(0); hash = Math.imul(hash, 16777619) >>> 0; }
  return hash % 128;
};
const literalPath = `/data/expanded-dictionary/${manifest.english.shards[bucket('apr.')].file}`;
const normalizedPath = `/data/expanded-dictionary/${manifest.english.shards[bucket('apr')].file}`;

test.use({ serviceWorkers: 'block', storageState: { cookies: [], origins: [] } });

function origin(baseURL) {
  if (!baseURL) throw new Error('This real-UI spec requires an explicitly configured owned baseURL.');
  const url = new URL(baseURL);
  if (!['127.0.0.1', 'localhost'].includes(url.hostname)) throw new Error('Fixture accounts are local only.');
  return url.origin;
}
async function open({ page, context, baseURL }, info, personal) {
  const base = origin(baseURL), calls = [];
  page.on('request', request => calls.push({ method: request.method(), url: request.url() }));
  page.on('pageerror', error => { throw error; });
  await context.addCookies([{ name: 'e2e_run', value: `literal-${createHash('sha256').update(info.testId).digest('hex').slice(0, 20)}`, url: base }]);
  if (personal) {
    const registered = await context.request.post(`${base}/api/v1/member/register`, {
      headers: { Origin: base, 'X-Wordbook-Auth': 'member' },
      data: { username: 'literal_reader', password: 'isolated literal lookup password 2026' }
    });
    expect(registered.status()).toBe(200);
    await page.goto(`${base}/personal.html?auth=member`);
    await expect(page.locator('#member-workspace')).toBeVisible();
    await expect(page.locator('#member-entry-list')).toHaveAttribute('aria-busy', 'false');
    await expect(page.locator('.personal-entry')).toHaveCount(0);
  } else await page.goto(`${base}/dictionary.html`);
  await expect(page.locator(personal ? '#member-dictionary-search' : '#dictionary-submit')).toBeEnabled();
  return { base, calls, personal };
}
function ids(personal) {
  return personal ? { input: '#member-dictionary-term', submit: '#member-dictionary-search', result: '#member-dictionary-result', term: '#member-dictionary-word', meaning: '#member-dictionary-meaning', pos: '#member-dictionary-pos' }
    : { input: '#dictionary-query', submit: '#dictionary-submit', result: '#dictionary-result', term: '#dictionary-term', meaning: '#dictionary-meaning', pos: '#dictionary-pos' };
}
async function query(page, personal, [input, term, meaning, pos]) {
  const ui = ids(personal);
  await page.locator(ui.input).fill(input);
  await page.locator(ui.input).press('Enter');
  await expect(page.locator(ui.submit)).toBeEnabled();
  await expect(page.locator(ui.result)).toBeVisible();
  await expect(page.locator(ui.term)).toHaveText(term);
  await expect(page.locator(ui.meaning)).toContainText(meaning);
  await expect(page.locator(ui.pos)).toContainText(pos);
  if (term === 'Apr.') await expect(page.locator(ui.meaning)).not.toContainText('年百分率');
  return { input, term: await page.locator(ui.term).innerText(), meaning: await page.locator(ui.meaning).innerText(), pos: await page.locator(ui.pos).innerText() };
}
function assertTraffic(state) {
  for (const call of state.calls) {
    const url = new URL(call.url);
    expect(url.origin, call.url).toBe(state.base);
    expect(['GET', 'HEAD'], call.url).toContain(call.method);
    if (!state.personal) expect(url.pathname).not.toMatch(/^\/api\//u);
    for (const name of ['q', 'query', 'term', 'word', 'lookup']) expect(url.searchParams.has(name), call.url).toBe(false);
  }
}

for (const width of [390, 1280]) for (const personal of [false, true]) {
  test(`literal precedence: ${personal ? 'personal fixture' : 'public'} actual lexical controls at ${width}px`, async ({ page, context, baseURL }, info) => {
    const args = { page, context, baseURL };
    test.setTimeout(60_000);
    await args.page.setViewportSize({ width, height: 844 });
    const state = await open(args, info, personal), observations = [];
    for (const item of cases) observations.push(await query(args.page, personal, item));
    if (personal) await expect(args.page.locator('.personal-entry')).toHaveCount(0);
    else {
      await query(args.page, false, cases[0]);
      await expect(args.page.locator('#dictionary-example-content p[lang="en"]').first()).toHaveText('The letter is dated 6 Apr.');
      await expect(args.page.locator('#dictionary-example-content p[lang="zh-CN"]').first()).toHaveText('这封信的日期是4月6日。');
    }
    expect(await args.page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth + 1)).toBe(true);
    assertTraffic(state);
    await info.attach('actual-lexical-observations', { body: JSON.stringify({ width, personal, observations, writes: 0 }, null, 2), contentType: 'application/json' });
  });
}

for (const personal of [false, true]) test(`literal precedence: ${personal ? 'personal compact race' : 'public'} waits for the genuine literal shard`, async ({ page, context, baseURL }, info) => {
  const state = await open({ page, context, baseURL }, info, personal), ui = ids(personal);
  // First use the legitimate compact finance result; it must not be reused
  // while a later month lookup is waiting for its distinct verified source.
  await query(page, personal, cases[5]);
  let release, reached;
  const gate = new Promise(done => { release = done; });
  const requested = new Promise(done => { reached = done; });
  await page.route(`**${literalPath}*`, async route => {
    const response = await route.fetch(); reached(); await gate;
    try { await route.fulfill({ response }); } catch { /* Closed/aborted callers cannot resurrect a result. */ }
  });
  try {
    await page.locator(ui.input).fill('“Ａｐｒ．”?!');
    await page.locator(ui.input).press('Enter');
    await requested;
    // Cross the compact race's 750ms grace while the real literal source is
    // deliberately unresolved; a later shortcut must not resurrect finance.
    await new Promise(resolve => setTimeout(resolve, 900));
    await expect(page.locator(ui.submit)).toBeDisabled();
    await expect(page.locator(ui.result)).toBeHidden();
    await expect(page.locator(ui.meaning)).not.toContainText('年百分率');
    release();
    await expect(page.locator(ui.submit)).toBeEnabled();
    await expect(page.locator(ui.term)).toHaveText('Apr.');
    await expect(page.locator(ui.meaning)).toContainText('四月');
    expect(state.calls.filter(call => new URL(call.url).pathname === normalizedPath)).toHaveLength(0);
    if (personal) await expect(page.locator('.personal-entry')).toHaveCount(0);
    assertTraffic(state);
  } finally { release(); }
});

test('literal precedence: actual browser fetch path is one verified literal shard and packaged ordinary controls remain request-free', async ({ page, baseURL }) => {
  await page.goto(`${origin(baseURL)}/dictionary.html`);
  const observed = await page.evaluate(async () => {
    const { searchExpandedDictionary } = await import('/js/expanded-dictionary.js?v=111');
    const run = async input => {
      const paths = [], fetchImpl = (url, options) => { paths.push(new URL(url).pathname); return fetch(url, options); };
      const value = await searchExpandedDictionary(input, { fetchImpl });
      return { input, paths, term: value.results[0]?.term, meaning: value.results[0]?.meaning };
    };
    const rows = [];
    for (const input of ['Apr.', '"Apr."', 'Ａｐｒ．', 'APR', 'data.', 'past.']) rows.push(await run(input));
    return rows;
  });
  for (const row of observed.slice(0, 3)) {
    expect(row.term).toBe('Apr.'); expect(row.meaning).toContain('四月');
    expect(row.paths).toEqual(['/data/expanded-dictionary/manifest.json', literalPath]);
  }
  for (const row of observed.slice(3)) expect(row.paths, row.input).toEqual([]);
});
